using LocalChat;
using System.Text.Json;
int passed=0;void Check(bool ok,string name){if(!ok)throw new Exception("FAIL "+name);Console.WriteLine("PASS "+name);passed++;}
const string goal="Создай сайт и опубликуй на Cloudflare";
string Call(string name,string code)=>JsonSerializer.Serialize(new{tool="mcp_call",server="cloudflare",name,arguments=new{code}});
void Enable(MainWindow h){var ts=h.mcpClients["cloudflare"].Tools;ts[0]=ts[0] with {Description="Actual API runtime cloudflare.request(options); async arrow function"};ts[1]=ts[1] with {Description="Search OpenAPI spec.paths using JavaScript async arrow function"};}
var h=new MainWindow();Enable(h);int turn=0;h.Result=a=>a.name=="search"?"MCP TOOL RESULT: actual paths /accounts/{account_id}/workers/scripts/{script_name} /accounts/{account_id}/workers/subdomain":"MCP TOOL RESULT: deployed https://contract.test.workers.dev";
LocalApi.Next=(m,f)=>{Check(h.Executed.Count>=1&&h.Executed[0].name=="search","real endpoint probe before model mutation");Check(m[0].content.Contains("cloudflare.request")&&m[0].content.Contains("spec.paths"),"runtime globals pinned in system prompt");Check(m[0].content.Contains("ACTUAL ENDPOINT CATALOGUE")&&m[0].content.Contains("workers/subdomain"),"actual catalogue pinned, not just generic Pages docs");return turn++ switch{0=>Call("execute","async () => { const pages = await import('cloudflare/pages'); return pages.createProject(); }"),1=>Call("execute","async () => { return cloudflare.request({method:'GET',path:'/accounts'}); }"),_=>"done"};};
var reply=await h.Run(goal);Check(h.Executed.Count(a=>a.name=="execute")==1,"phantom SDK import rejected locally without remote execute");Check(reply.ToolResults.Any(x=>x.Contains("Local Cloudflare code-mode check")),"local error visible with actual correction advice");Check(reply.Text.Contains("contract.test.workers.dev"),"subsequent corrected action completes with receipt");Check(h.Checkpoint!.Steps.Count(x=>x.Name=="search")==2,"schema plus one real endpoint probe in ledger");
// Contract survives older result trimming, including more than six intervening actions.
h=new();Enable(h);turn=0;h.Result=a=>a.name=="search"?"MCP TOOL RESULT: paths from spec.paths":"fresh observation "+h.Executed.Count;LocalApi.Next=(m,f)=>{Check(m[0].content.Contains("cloudflare.request")&&m[0].content.Contains("spec.paths"),"contract retained after tool history trimming "+turn);return turn++<8?JsonSerializer.Serialize(new{tool="browser_snapshot",query="observation"+turn}):Call("execute","async () => { return cloudflare.request({method:'GET',path:'/accounts'}); }");};
using(var c=new CancellationTokenSource()){int count=0;h.BeforeExecute=a=>{if(++count==11)c.Cancel();};try{await h.Run(goal,c.Token);}catch(OperationCanceledException){}}
// Resume reuses completed endpoint discovery, no blind search/execute replay.
h=new();Enable(h);var t=new AgentTask{ChatId=h.current.Id,Goal=goal,Status="paused"};var probe=new ToolCall("mcp_call",server:"cloudflare",name:"search",arguments:JsonSerializer.SerializeToElement(new{code=CloudflareCodeMode.SearchCode}));t.End(t.Begin(probe),"MCP TOOL RESULT: stored catalogue");h.PutCheckpoint(t);h.Result=_=>"MCP TOOL RESULT: deployed https://resume.test.workers.dev";turn=0;LocalApi.Next=(m,f)=>turn++==0?Call("execute","async () => { return cloudflare.request({method:'GET',path:'/accounts'}); }"):"done";reply=await h.Run("продолжай");Check(h.Executed.Count(a=>a.name=="search")==0,"checkpoint prevents duplicate discovery probe");
h=new();Enable(h);h.Result=_=>"Пользователь запретил действие";int modelCalls=0;LocalApi.Next=(_,_)=>{modelCalls++;return "done";};bool denied=false;try{await h.Run(goal);}catch(OperationCanceledException){denied=true;}Check(denied&&modelCalls==0,"bootstrap denial honored before any model mutation");
h=new();turn=0;h.Result=_=>"MCP TOOL RESULT: deployed https://other.test.workers.dev";LocalApi.Next=(_,_)=>turn++==0?Call("execute","opaque fixture code"):"done";await h.Run(goal);Check(h.Executed.All(a=>a.name!="search"),"no assumptions for non-code-mode tool descriptions");
h=new();Enable(h);LocalApi.Next=(_,_)=>"Привет!";await h.Run("привет");Check(h.Executed.Count==0,"ordinary conversation does not trigger remote discovery");
Check(CloudflareCodeMode.InvalidImport(new ToolCall("mcp_call",server:"cloudflare",name:"execute",arguments:JsonSerializer.SerializeToElement(new{code="async () => { const html = 'a'; return html; }"})),true)==null,"plain generated source not blocked");
Console.WriteLine($"{passed} Cloudflare318 checks passed");
